import { buildKnowledgeGraph, weightedVoting } from './graphUtils';

export function crossAgentConsensus(agentOutputs) {
  const knowledgeGraph = buildKnowledgeGraph(agentOutputs);
  const consensus = weightedVoting(knowledgeGraph);
  return consensus;
}

export function buildKnowledgeGraph(agentOutputs) {
  const graph = {};
  agentOutputs.forEach(output => {
    graph[output.agentId] = output.data;
  });
  return graph;
}

export function weightedVoting(graph) {
  const votes = Object.entries(graph).map(([agentId, data]) => {
    const weight = data.confidence;
    return { agentId, weight, decision: data.decision };
  });
  const consensus = votes.reduce((best, vote) => {
    return vote.weight > best.weight ? vote : best;
  }, { weight: 0 });
  return consensus;
}